contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address _recipient) public {
        require(c.owner() == address(this));
        require(_recipient != address(0));
        uint256 balBefore = address(c).balance;
        uint256 recipBefore = _recipient.balance;
        c.withdrawAll(_recipient); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && _recipient.balance == recipBefore + balBefore);
    }
    receive() external payable {}
}

